<link rel="stylesheet" href="<?=asset('css/publishing.css')?>"><link rel="stylesheet" href="<?=asset('css/google-workspace.css')?>">
<main class="write-main pub-main google-workspace" data-google-actions>
<header class="writer-head"><div><span class="writer-kicker">Prepare · review · create</span><h1>Google action studio</h1><p>Create a document, spreadsheet or task in your confirmed Google account.</p></div><a class="wbtn" href="<?=url('/write/google')?>">Google workspace</a></header>
<?php if($error!==''):?><p class="pub-card" role="alert"><?=e($error)?></p><?php endif;?>
<?php if($part==='new'):?>
<section class="pub-card"><h2>Prepare your content</h2><p>Docs and Sheets are created as new private files in My Drive. Tasks use the list you confirmed in Connections. Existing files stay intact.</p>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="prepare">
<label class="pub-field">Create<select name="kind"><?php foreach(gwa_types()as$key=>$label):?><option value="<?=$key?>" <?=($values['kind']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label class="pub-field">Title<input name="title" maxlength="200" required value="<?=e($values['title']??'')?>"></label>
<label class="pub-field">Selected content<textarea name="text" rows="12" maxlength="60000" aria-describedby="google-content-help"><?=e($values['text']??'')?></textarea></label>
<p id="google-content-help">For a Doc, paste your reviewed text. For a Sheet, paste a table with tabs between columns and a new line for each row (up to 200 rows and 20 columns). Cells are stored as literal text, including anything beginning with “=”. For a Task, this becomes its optional notes (up to 6,000 bytes).</p>
<label class="pub-field">Task due date · optional<input type="date" name="due" value="<?=e($values['due']??'')?>"><small>Tasks use a date, not a timed appointment. This field is ignored for Docs and Sheets.</small></label>
<label class="pub-check"><input type="checkbox" name="content_consent" value="1" required> This selected content is intended for my confirmed Google account.</label>
<button class="wbtn primary">Save for review</button> <a href="<?=url('/write/google/actions')?>">Back to actions</a></form></section>
<?php elseif($record):?>
<section class="pub-card"><span class="status"><?=e(str_replace('_',' ',$record['state']))?></span><h2><?=e($record['title'])?></h2>
<dl><dt>Action</dt><dd><?=e(gwa_types()[$record['kind']])?></dd><dt>Account</dt><dd><?=e($record['account_name'])?></dd><dt>Destination</dt><dd><?=e($record['destination'])?></dd><?php if($record['due']!==''):?><dt>Due date</dt><dd><?=e($record['due'])?></dd><?php endif;?></dl>
<?php if($record['kind']==='sheet'):?><div class="pub-table-wrap"><table class="pub-table"><caption>Exact spreadsheet content</caption><tbody><?php foreach(gwa_rows($record['text'])as$row):?><tr><?php foreach($row as$cell):?><td><?=e($cell)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php else:?><pre class="google-action-text"><?=e($record['text'])?></pre><?php endif;?>
<?php if(!empty($record['outcome'])):?><p role="status"><?=e($record['outcome'])?></p><?php endif;?>
<?php if(!empty($record['remote_status'])):?><p>Google Task status: <?=e($record['remote_status'])?>. Your local programme is unchanged.</p><?php endif;?>
<?php if(!empty($record['url'])):?><p><a class="wbtn" href="<?=e($record['url'])?>" target="_blank" rel="noopener noreferrer">Open verified Google result ↗</a></p><?php endif;?>
<?php if(in_array($record['state'],['draft','reviewed'],true)):?>
<form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><input type="hidden" name="action" value="<?=$record['state']==='draft'?'review':'apply'?>"><label class="pub-check"><input type="checkbox" name="confirm" value="1" required> <?=$record['state']==='draft'?'I have reviewed this account, destination and exact content.':'Create this exact record in the displayed Google account now.'?></label><button class="wbtn primary"><?=$record['state']==='draft'?'Confirm review':'Create in Google'?></button></form>
<?php if($record['state']==='reviewed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><input type="hidden" name="action" value="review"><label class="pub-check"><input type="checkbox" name="confirm" value="1" required> I have reviewed this exact content again.</label><button class="wbtn">Renew review</button><p>Reviews expire after 30 minutes.</p></form><?php endif;?>
<form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><button class="wbtn" name="action" value="discard">Discard this unused action</button></form>
<?php endif;?>
<?php if(in_array($record['state'],['unknown','verification_pending','done'],true)&&!empty($record['remote_id'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><button class="wbtn" name="action" value="recheck">Check existing result</button><p>This reads the known Google record without creating another copy.</p></form><?php endif;?>
<details><summary>Action history</summary><ol><?php foreach($record['audit']as$entry):?><li><?=e(gmdate('j M Y H:i',$entry['at']).' UTC · '.str_replace('_',' ',$entry['state']))?></li><?php endforeach;?></ol></details><p><a href="<?=url('/write/google/actions')?>">All actions</a></p></section>
<?php else:?>
<section class="pub-card"><h2>Choose what to create</h2><p>Prepare selected text or a table, review the destination, then create it once. A failed or uncertain creation remains visible for review.</p><a class="wbtn primary" href="<?=url('/write/google/actions/new')?>">Prepare a Google action</a></section>
<section class="pub-card"><h2>Connections</h2><?php foreach(['document'=>'Docs & Sheets','task'=>'Google Tasks']as$kind=>$name):?><div><h3><?=e($name)?></h3><?php try{$connection=gwa_ready($kind,$uid);?><p>Confirmed account: <?=e($connection['display_name'])?>. Destination: <?=e($kind==='task'?$connection['selected_resource']:'My Drive')?>.</p><?php }catch(GoogleActionException $connectionError){?><p><?=e($connectionError->getMessage())?></p><?php }?><a href="<?=url('/write/connections#'.gwa_service($kind))?>">Review connection</a></div><?php endforeach;?></section>
<section class="pub-card"><h2>Your actions</h2><?php if(!$records):?><p>No actions prepared yet.</p><?php endif;?><?php foreach($records as$row):?><article class="google-action-row"><h3><a href="<?=url('/write/google/actions/'.$row['id'])?>"><?=e($row['title'])?></a></h3><p><?=e(gwa_types()[$row['kind']].' · '.str_replace('_',' ',$row['state']))?></p></article><?php endforeach;?></section>
<?php endif;?></main>
